import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, calculateDueDate } from './dates.js';
import { lineTotal, invoiceTotals } from './totals.js';

/**
 * Create a draft invoice from a customer id and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }>, terms: string, dueDate: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Validate customer exists
  const customer = getCustomer(customerId);
  if (!customer.ok) {
    return fail('CUSTOMER_NOT_FOUND');
  }

  // Validate issueDate format
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate and calculate due date based on terms
  const dueDate = calculateDueDate(issueDate, terms);
  if (!dueDate) {
    return fail('TERMS_INVALID');
  }

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Get product from catalogue
    const product = getProduct(line.sku);
    if (!product.ok) {
      return fail('UNKNOWN_SKU');
    }

    const p = product.value;
    const lineObj = {
      sku: line.sku,
      name: p.name,
      qty: line.qty,
      unitPrice: p.unitPrice,
      vatRate: p.vatRate,
    };

    // Set discountPercent: explicit value takes precedence over tier discount
    if (line.discountPercent !== undefined) {
      lineObj.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.value.tier] ?? 0;
      if (tierDiscount > 0) {
        lineObj.discountPercent = tierDiscount;
      }
    }

    enrichedLines.push(lineObj);
  }

  return ok({
    customerId: normalizeId(customerId),
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms,
    dueDate,
  });
}

