import { formatEuros } from './money.js';
import { invoiceTotals, lineTotal } from './invoices.js';
import { getCustomer } from './customers.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, dueDate?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number }, payments?: Array<{ amount: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  // First line: invoice number or DRAFT
  const numberLine = invoice.number ?? 'DRAFT';

  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  // Build line items
  const lineItems = invoice.lines
    .map((line) => {
      const total = lineTotal(line);
      const unitPriceFormatted = formatEuros(line.unitPrice);
      const totalFormatted = formatEuros(total);
      let lineStr = `${line.qty} × ${line.name} @ ${unitPriceFormatted} = ${totalFormatted}`;

      // Collect all discounts for this line
      const discounts = [];
      if (line.discountPercent !== undefined && line.discountPercent > 0) {
        const lineDiscount = Math.round(total * line.discountPercent / 100);
        discounts.push(`${line.discountPercent}% off: -${formatEuros(lineDiscount)}`);
      }

      // Add bulk discount if applicable (qty >= 10)
      if (line.qty >= 10) {
        const afterLineDiscount = line.discountPercent ? total - Math.round(total * line.discountPercent / 100) : total;
        const bulkDiscount = Math.round(afterLineDiscount * 2.5 / 100);
        if (bulkDiscount > 0) {
          discounts.push(`bulk: -${formatEuros(bulkDiscount)}`);
        }
      }

      if (discounts.length > 0) {
        lineStr += ` (${discounts.join(', ')})`;
      }
      return lineStr;
    });

  // Calculate and format totals
  const totals = invoiceTotals(invoice);
  const output = [numberLine, customerName, ...lineItems];

  // Add subtotal if there are discounts or VAT
  if (totals.discount > 0 || totals.vat > 0) {
    output.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
  }

  // Add discount line if discount exists
  if (totals.discount > 0) {
    output.push(`Discount: -${formatEuros(totals.discount)}`);
  }

  // Add VAT line if VAT exists
  if (totals.vat > 0) {
    output.push(`VAT: +${formatEuros(totals.vat)}`);
  }

  // Add voucher line if voucher exists
  if (totals.voucher > 0) {
    output.push(`Voucher: -${formatEuros(totals.voucher)}`);
  }

  output.push(`Total: ${formatEuros(totals.total)}`);

  // Add due date if available
  if (invoice.dueDate) {
    output.push(`Due: ${invoice.dueDate}`);
  }

  // Add paid amount if there are payments
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    output.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return output.join('\n');
}

