  assert.ok(voucherResult.ok);

  const text = renderInvoiceText(voucherResult.value);

  // Total before voucher: 91960, voucher: 5000 = €50, total after: 86960 = €869.60
  assert.ok(text.includes('Voucher: -€50.00'));
  assert.ok(text.includes('Total: €869.60'));
});

