test('renderInvoiceText: all features combined', () => {
  const invResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
    terms: 'NET14',
  });

  assert.ok(invResult.ok);
  const issued = issueInvoice(invResult.value, []);
  assert.ok(issued.ok);

  const voucher = applyVoucher(issued.value, { code: 'WELCOME', amount: 2000 });
  assert.ok(voucher.ok);

  const payment = recordPayment(voucher.value, { amount: 25000, date: '2026-10-10' });
  assert.ok(payment.ok);

  const text = renderInvoiceText(payment.value);

  assert.ok(text.includes('Development (hour)'));
  assert.ok(text.includes('Design work (hour)'));
  assert.ok(text.includes('Discount:'));
  assert.ok(text.includes('VAT:'));
  assert.ok(text.includes('Voucher: -€20.00'));
  assert.ok(text.includes('Total:'));
  assert.ok(text.includes('Due: 2026-10-21'));
  assert.ok(text.includes('Paid: €250.00'));
});

